package net.zartra.gui;
import static org.junit.Assert.*;import java.util.*;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;
public class LosslessVariantRegressionTest {
 @Test public void capturedStackSerializationSurvivesCopyAndRender(){ItemStack source=new ItemStack(Material.WOOL,7,(short)11);MenuItem item=new MenuItem(source,null);assertFalse(item.stackSnapshot.isEmpty());MenuItem copy=item.copy();ItemStack rendered=copy.stack();assertEquals(Material.WOOL,rendered.getType());assertEquals(7,rendered.getAmount());assertEquals(11,rendered.getDurability());assertEquals(item.stackSnapshot,copy.stackSnapshot);}
 @Test public void modernIdentityIsPersistedAsOpaqueStackSnapshot()throws Exception{String model=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/MenuItem.java")),"UTF-8");String storage=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/MenuStorage.java")),"UTF-8");assertTrue(model.contains("stack.serialize()"));assertTrue(model.contains("ItemStack.deserialize"));assertTrue(storage.contains("stack-snapshot"));}
 @Test public void editorUsesVirtualNaturalTransactionsInsteadOfSpecialMoveModes()throws Exception{String source=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/GuiListener.java")),"UTF-8");assertTrue(source.contains("gui.virtualClick(e,p,d,top)"));assertTrue(source.contains("gui.virtualDrag"));assertFalse(source.contains("gui.beginMove(p,d,raw)"));assertFalse(source.contains("gui.removeItem(p,d,raw)"));}
}